# Logo da empresa para uso nos templates de e-mail (CID inline)
LOGO_CID = "uneworld-logo"
LOGO_B64_CONTENT = ""


def get_logo_src():
    """Retorna src do logo: URL pública se BACKEND_URL configurado, senão CID fallback."""
    from django.conf import settings
    backend = getattr(settings, 'BACKEND_URL', '').rstrip('/')
    if backend and not backend.startswith('http://localhost') and not backend.startswith('http://127.0.0.1'):
        return backend + '/assets/logo.png', False  # (src, use_attachment)
    return f'cid:{LOGO_CID}', True  # fallback CID
